package com.afkhelper;

import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Skill;

public class AfkHelperActionTracker
{
    private final Map<Skill, Integer> lastAnimations =
            new EnumMap<>(Skill.class);

    private final Map<Skill, Boolean> wasActive =
            new EnumMap<>(Skill.class);

    public boolean shouldRecordAction(Skill skill, int animationId)
    {
        if (skill == null || animationId < 0)
        {
            return false;
        }

        Integer previousAnimation = lastAnimations.get(skill);
        boolean previouslyActive = wasActive.getOrDefault(skill, false);

        boolean newAction =
                !previouslyActive
                        || previousAnimation == null
                        || previousAnimation != animationId;

        lastAnimations.put(skill, animationId);
        wasActive.put(skill, true);

        return newAction;
    }

    public void markIdle(Skill skill)
    {
        if (skill != null)
        {
            wasActive.put(skill, false);
        }
    }

    public void reset()
    {
        lastAnimations.clear();
        wasActive.clear();
    }
}

package com.afkhelper;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Set;
import java.util.Locale;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Player;
import net.runelite.api.Perspective;
import net.runelite.api.Skill;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

public class AfkHelperActivityHighlightOverlay extends Overlay
{
    private static final Color ELIGIBLE_COLOR =
            new Color(40, 220, 100, 45);
    private static final Color ELIGIBLE_OUTLINE =
            new Color(70, 255, 130, 150);

    private static final Color INELIGIBLE_COLOR =
            new Color(230, 65, 65, 35);
    private static final Color INELIGIBLE_OUTLINE =
            new Color(255, 90, 90, 145);

    private static final Color LABEL_BACKGROUND =
            new Color(20, 20, 20, 210);
    private static final Color ELIGIBLE_TEXT =
            new Color(120, 255, 160);
    private static final Color INELIGIBLE_TEXT =
            new Color(255, 130, 130);

    private final Client client;
    private final AfkHelperConfig config;

    // Only objects that could be a skilling activity are remembered. They
    // are added and removed from spawn/despawn events instead of scanning
    // every tile in the scene each frame. Identity-based, so an object that
    // covers several tiles (a tree) is only stored and drawn once. Events and
    // overlay rendering both run on the client thread.
    private final Set<TileObject> trackedObjects =
            Collections.newSetFromMap(new IdentityHashMap<>());

    // Don't bother drawing objects further away than this.
    private static final int MAX_DISTANCE_TILES = 25;

    public AfkHelperActivityHighlightOverlay(
            Client client,
            AfkHelperConfig config)
    {
        this.client = client;
        this.config = config;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
        setPriority(OverlayPriority.HIGH);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.enabled()
                || !config.eligibleActivityHighlightingEnabled()
                || !config.skillingMonitoring()
                || client.getGameState() != GameState.LOGGED_IN
                || client.getScene() == null)
        {
            return null;
        }

        Player localPlayer = client.getLocalPlayer();

        if (localPlayer == null || trackedObjects.isEmpty())
        {
            return null;
        }

        LocalPoint playerLocation = localPlayer.getLocalLocation();

        if (playerLocation == null)
        {
            return null;
        }

        for (TileObject object : trackedObjects)
        {
            renderObject(graphics, object, playerLocation);
        }

        return null;
    }

    /** Remember an object if it could be a skilling activity. */
    public void objectSpawned(TileObject object)
    {
        if (mightBeActivity(object))
        {
            trackedObjects.add(object);
        }
    }

    public void objectDespawned(TileObject object)
    {
        if (object != null)
        {
            trackedObjects.remove(object);
        }
    }

    public void clear()
    {
        trackedObjects.clear();
    }

    /**
     * One-off scan of the loaded scene, for when the plugin is switched on
     * while already logged in. After this, spawn events keep things current.
     * Must be called on the client thread.
     */
    public void scanScene()
    {
        trackedObjects.clear();

        if (client.getGameState() != GameState.LOGGED_IN
                || client.getScene() == null)
        {
            return;
        }

        Tile[][][] tiles = client.getScene().getTiles();

        if (tiles == null)
        {
            return;
        }

        for (Tile[][] plane : tiles)
        {
            if (plane == null)
            {
                continue;
            }

            for (Tile[] row : plane)
            {
                if (row == null)
                {
                    continue;
                }

                for (Tile tile : row)
                {
                    if (tile == null)
                    {
                        continue;
                    }

                    objectSpawned(tile.getWallObject());
                    objectSpawned(tile.getDecorativeObject());
                    objectSpawned(tile.getGroundObject());

                    GameObject[] gameObjects = tile.getGameObjects();

                    if (gameObjects != null)
                    {
                        for (GameObject gameObject : gameObjects)
                        {
                            objectSpawned(gameObject);
                        }
                    }
                }
            }
        }
    }

    /**
     * Cheap, config-independent check done once when an object appears.
     * Objects that morph (impostors) can't be judged until they are
     * resolved, so they are kept and checked properly when drawn.
     */
    private boolean mightBeActivity(TileObject object)
    {
        if (object == null || object.getId() <= 0)
        {
            return false;
        }

        if (object instanceof GameObject
                && ((GameObject) object).getRenderable() instanceof Actor)
        {
            return false;
        }

        ObjectComposition composition =
                client.getObjectDefinition(object.getId());

        if (composition == null)
        {
            return false;
        }

        if (composition.getImpostorIds() != null)
        {
            return true;
        }

        String[] actions = composition.getActions();

        if (actions == null)
        {
            return false;
        }

        for (String action : actions)
        {
            if (action == null)
            {
                continue;
            }

            String normalised = action.toLowerCase(Locale.ROOT).trim();

            if (normalised.startsWith("chop")
                    || normalised.equals("mine")
                    || isFishingAction(normalised)
                    || normalised.equals("catch")
                    || normalised.equals("check"))
            {
                return true;
            }
        }

        return false;
    }

    private void renderObject(
            Graphics2D graphics,
            TileObject object,
            LocalPoint playerLocation)
    {
        if (object == null || object.getId() <= 0)
        {
            return;
        }

        // Players and NPCs can appear in a tile's game object list. Their
        // "id" is not an object id, so looking it up can match an unrelated
        // object (for example a tree) and put a highlight on a moving actor.
        if (object instanceof GameObject
                && ((GameObject) object).getRenderable() instanceof Actor)
        {
            return;
        }

        ObjectComposition composition =
                client.getObjectDefinition(object.getId());

        if (composition == null)
        {
            return;
        }

        // Only resolve an impostor when the object actually has impostors.
        // Calling getImpostor() without this check can throw a
        // NullPointerException in RuneLite.
        int[] impostorIds = composition.getImpostorIds();

        if (impostorIds != null)
        {
            ObjectComposition impostor = composition.getImpostor();

            if (impostor == null)
            {
                return;
            }

            composition = impostor;
        }

        ActivityRequirement requirement =
                getActivityRequirement(composition);

        if (requirement == null)
        {
            return;
        }

        if (!isSkillEnabled(requirement.skill))
        {
            return;
        }

        int playerLevel = client.getRealSkillLevel(requirement.skill);
        boolean eligible = playerLevel >= requirement.level;

        if (object.getPlane() != client.getPlane())
        {
            return;
        }

        LocalPoint localPoint = object.getLocalLocation();

        if (localPoint == null
                || localPoint.distanceTo(playerLocation)
                > MAX_DISTANCE_TILES * Perspective.LOCAL_TILE_SIZE)
        {
            return;
        }

        Polygon polygon =
                Perspective.getCanvasTilePoly(client, localPoint);

        if (polygon == null)
        {
            return;
        }

        if (eligible)
        {
            graphics.setColor(ELIGIBLE_COLOR);
            graphics.fillPolygon(polygon);
            graphics.setColor(ELIGIBLE_OUTLINE);
        }
        else
        {
            graphics.setColor(INELIGIBLE_COLOR);
            graphics.fillPolygon(polygon);
            graphics.setColor(INELIGIBLE_OUTLINE);
        }

        graphics.drawPolygon(polygon);

        String label = requirement.level + " " + requirement.skillName;

        drawRequirementLabel(
                graphics,
                polygon,
                label,
                eligible);
    }

    private ActivityRequirement getActivityRequirement(
            ObjectComposition composition)
    {
        String name = composition.getName();

        if (name == null)
        {
            return null;
        }

        String normalisedName = name.toLowerCase(Locale.ROOT);
        String[] actions = composition.getActions();

        if (actions == null)
        {
            return null;
        }

        for (String action : actions)
        {
            if (action == null)
            {
                continue;
            }

            String normalisedAction =
                    action.toLowerCase(Locale.ROOT).trim();

            if (config.woodcuttingMonitoring()
                    && normalisedAction.startsWith("chop"))
            {
                return getWoodcuttingRequirement(normalisedName);
            }

            if (config.miningMonitoring()
                    && normalisedAction.equals("mine"))
            {
                return getMiningRequirement(normalisedName);
            }

            if (config.fishingMonitoring()
                    && isFishingAction(normalisedAction))
            {
                return getFishingRequirement(normalisedName);
            }

            if (config.hunterMonitoring()
                    && (normalisedAction.equals("catch")
                    || normalisedAction.equals("check")))
            {
                return getHunterRequirement(normalisedName);
            }
        }

        return null;
    }

    private ActivityRequirement getWoodcuttingRequirement(String name)
    {
        if (name.contains("redwood"))
        {
            return requirement(Skill.WOODCUTTING, 90);
        }

        if (name.contains("magic"))
        {
            return requirement(Skill.WOODCUTTING, 75);
        }

        if (name.contains("yew"))
        {
            return requirement(Skill.WOODCUTTING, 60);
        }

        if (name.contains("mahogany"))
        {
            return requirement(Skill.WOODCUTTING, 50);
        }

        if (name.contains("maple"))
        {
            return requirement(Skill.WOODCUTTING, 45);
        }

        if (name.contains("teak"))
        {
            return requirement(Skill.WOODCUTTING, 35);
        }

        if (name.contains("willow"))
        {
            return requirement(Skill.WOODCUTTING, 30);
        }

        if (name.contains("oak"))
        {
            return requirement(Skill.WOODCUTTING, 15);
        }

        if (name.contains("tree")
                || name.contains("dead tree")
                || name.contains("achey"))
        {
            return requirement(Skill.WOODCUTTING, 1);
        }

        return null;
    }

    private ActivityRequirement getMiningRequirement(String name)
    {
        if (name.contains("runite"))
        {
            return requirement(Skill.MINING, 85);
        }

        if (name.contains("adamant"))
        {
            return requirement(Skill.MINING, 70);
        }

        if (name.contains("mithril"))
        {
            return requirement(Skill.MINING, 55);
        }

        if (name.contains("amethyst"))
        {
            return requirement(Skill.MINING, 92);
        }

        if (name.contains("gold"))
        {
            return requirement(Skill.MINING, 40);
        }

        if (name.contains("coal"))
        {
            return requirement(Skill.MINING, 30);
        }

        if (name.contains("silver"))
        {
            return requirement(Skill.MINING, 20);
        }

        if (name.contains("iron"))
        {
            return requirement(Skill.MINING, 15);
        }

        if (name.contains("copper")
                || name.contains("tin")
                || name.contains("clay")
                || name.contains("gem"))
        {
            return requirement(Skill.MINING, 1);
        }

        return null;
    }

    private boolean isFishingAction(String action)
    {
        return action.equals("fish")
                || action.equals("net")
                || action.equals("bait")
                || action.equals("lure")
                || action.equals("harpoon")
                || action.equals("cage");
    }

    private ActivityRequirement getFishingRequirement(String name)
    {
        if (name.contains("anglerfish"))
        {
            return requirement(Skill.FISHING, 82);
        }

        if (name.contains("dark crab"))
        {
            return requirement(Skill.FISHING, 85);
        }

        if (name.contains("shark"))
        {
            return requirement(Skill.FISHING, 76);
        }

        if (name.contains("monkfish"))
        {
            return requirement(Skill.FISHING, 62);
        }

        if (name.contains("karambwan"))
        {
            return requirement(Skill.FISHING, 65);
        }

        if (name.contains("swordfish"))
        {
            return requirement(Skill.FISHING, 50);
        }

        if (name.contains("lobster"))
        {
            return requirement(Skill.FISHING, 40);
        }

        if (name.contains("tuna"))
        {
            return requirement(Skill.FISHING, 35);
        }

        if (name.contains("salmon"))
        {
            return requirement(Skill.FISHING, 30);
        }

        if (name.contains("trout"))
        {
            return requirement(Skill.FISHING, 20);
        }

        if (name.contains("herring"))
        {
            return requirement(Skill.FISHING, 10);
        }

        if (name.contains("sardine"))
        {
            return requirement(Skill.FISHING, 5);
        }

        if (name.contains("shrimp")
                || name.contains("anchov")
                || name.contains("fishing spot"))
        {
            return requirement(Skill.FISHING, 1);
        }

        return null;
    }

    private ActivityRequirement getHunterRequirement(String name)
    {
        if (name.contains("black chinchompa"))
        {
            return requirement(Skill.HUNTER, 73);
        }

        if (name.contains("red chinchompa"))
        {
            return requirement(Skill.HUNTER, 63);
        }

        if (name.contains("chinchompa"))
        {
            return requirement(Skill.HUNTER, 53);
        }

        if (name.contains("black salamander"))
        {
            return requirement(Skill.HUNTER, 67);
        }

        if (name.contains("red salamander"))
        {
            return requirement(Skill.HUNTER,  salamanderLevel(name));
        }

        if (name.contains("orange salamander"))
        {
            return requirement(Skill.HUNTER, 47);
        }

        if (name.contains("salamander"))
        {
            return requirement(Skill.HUNTER, 29);
        }

        if (name.contains("bird snare"))
        {
            return requirement(Skill.HUNTER, 5);
        }

        if (name.contains("butterfly"))
        {
            return requirement(Skill.HUNTER, 15);
        }

        if (name.contains("rabbit snare"))
        {
            return requirement(Skill.HUNTER, 27);
        }

        if (name.contains("box trap"))
        {
            return requirement(Skill.HUNTER, 27);
        }

        return null;
    }

    private int salamanderLevel(String name)
    {
        if (name.contains("red salamander"))
        {
            return  salamanderLevelForRed();
        }

        return 1;
    }

    private int salamanderLevelForRed()
    {
        return  redSalamanderRequiredLevel();
    }

    private int redSalamanderRequiredLevel()
    {
        return  redSalamanderLevel();
    }

    private int redSalamanderLevel()
    {
        return 47;
    }

    private ActivityRequirement requirement(Skill skill, int level)
    {
        return new ActivityRequirement(skill, level);
    }

    private boolean isSkillEnabled(Skill skill)
    {
        if (!config.skillingMonitoring())
        {
            return false;
        }

        switch (skill)
        {
            case WOODCUTTING:
                return config.woodcuttingMonitoring();

            case MINING:
                return config.miningMonitoring();

            case FISHING:
                return config.fishingMonitoring();

            case HUNTER:
                return config.hunterMonitoring();

            default:
                return false;
        }
    }

    private void drawRequirementLabel(
            Graphics2D graphics,
            Polygon polygon,
            String text,
            boolean eligible)
    {
        FontMetrics metrics = graphics.getFontMetrics();

        int textWidth = metrics.stringWidth(text);
        int textHeight = metrics.getHeight();

        int padding = 4;
        int labelWidth = textWidth + padding * 2;
        int labelHeight = textHeight + padding;

        int x = polygon.getBounds().x
                + (polygon.getBounds().width - labelWidth) / 2;

        int y = polygon.getBounds().y - labelHeight;

        if (y < 0)
        {
            y = polygon.getBounds().y + 2;
        }

        graphics.setColor(LABEL_BACKGROUND);
        graphics.fillRoundRect(
                x, y, labelWidth, labelHeight, 5, 5);

        graphics.setColor(
                eligible ? ELIGIBLE_TEXT : INELIGIBLE_TEXT);

        graphics.drawString(
                text,
                x + padding,
                y + metrics.getAscent());
    }

    private static class ActivityRequirement
    {
        private final Skill skill;
        private final int level;
        private final String skillName;

        private ActivityRequirement(Skill skill, int level)
        {
            this.skill = skill;
            this.level = level;

            switch (skill)
            {
                case WOODCUTTING:
                    skillName = "Woodcutting";
                    break;

                case MINING:
                    skillName = "Mining";
                    break;

                case FISHING:
                    skillName = "Fishing";
                    break;

                case HUNTER:
                    skillName = "Hunter";
                    break;

                default:
                    skillName = skill.getName();
                    break;
            }
        }
    }
}

package com.afkhelper;

import net.runelite.api.Client;
import net.runelite.api.GameState;

public class AfkHelperAfkCountdown
{
    // Client ticks are 20ms, so there are 50 per second.
    private static final int TICKS_PER_SECOND = 50;

    private final Client client;
    private final AfkHelperInputTracker inputTracker;

    public AfkHelperAfkCountdown(
            Client client,
            AfkHelperInputTracker inputTracker)
    {
        this.client = client;
        this.inputTracker = inputTracker;
    }

    public int getIdleSeconds()
    {
        return Math.max(0, inputTracker.getIdleTicks() / TICKS_PER_SECOND);
    }

    public int getSecondsUntilLogout(int idleTimeoutTicks)
    {
        int timeoutSeconds =
                Math.max(0, idleTimeoutTicks / TICKS_PER_SECOND);
        return Math.max(0, timeoutSeconds - getIdleSeconds());
    }

    public boolean isLogoutWarningDue(
            int idleTimeoutTicks,
            int warningSeconds)
    {
        int remaining = getSecondsUntilLogout(idleTimeoutTicks);

        return remaining > 0 && remaining <= warningSeconds;
    }

    public String getIdleTimeText()
    {
        return formatTime(getIdleSeconds());
    }

    public String getLogoutCountdownText(int warningSeconds)
    {
        return getLogoutCountdownText(15000, warningSeconds);
    }

    public String getLogoutCountdownText(
            int idleTimeoutTicks,
            int warningSeconds)
    {
        int remaining = getSecondsUntilLogout(idleTimeoutTicks);

        if (remaining > warningSeconds)
        {
            return "Not imminent";
        }

        return formatTime(remaining);
    }

    public boolean isPlayerActive()
    {
        return client.getGameState() == GameState.LOGGED_IN
                && client.getLocalPlayer() != null;
    }

    public String formatTime(int seconds)
    {
        int safeSeconds = Math.max(0, seconds);
        int minutes = safeSeconds / 60;
        int remainingSeconds = safeSeconds % 60;

        return String.format("%02d:%02d", minutes, remainingSeconds);
    }
}

package com.afkhelper;

import java.io.ByteArrayInputStream;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;

/**
 * Plays the short synthesised alert sounds through RuneLite's AudioPlayer.
 * The whole sound (tones and the gaps between them) is rendered into one
 * in-memory WAV file, so nothing needs to sleep, and playback is handed to
 * RuneLite's shared executor rather than a thread of our own. Only one
 * alert plays at a time; a new one requested while another is still
 * sounding is skipped.
 */
@Slf4j
@Singleton
public class AfkHelperAudioPlayer
{
    private static final int SAMPLE_RATE = 44100;
    private static final int GAP_MS = 70;

    private final AudioPlayer audioPlayer;
    private final ScheduledExecutorService executor;

    private volatile boolean stopped;
    private volatile long soundingUntilMillis;

    @Inject
    public AfkHelperAudioPlayer(
            AudioPlayer audioPlayer,
            ScheduledExecutorService executor)
    {
        this.audioPlayer = audioPlayer;
        this.executor = executor;
    }

    /** Allow sounds to play (call when the plugin starts). */
    public void start()
    {
        stopped = false;
    }

    /** Refuse new sounds (call when the plugin stops). */
    public void stop()
    {
        stopped = true;
    }

    public void play(AfkHelperConfig.AlertSound sound, int volume)
    {
        if (sound == null || stopped || volume <= 0)
        {
            return;
        }

        long now = System.currentTimeMillis();

        if (now < soundingUntilMillis)
        {
            return;
        }

        int[][] tones = getTones(sound);
        soundingUntilMillis = now + getDurationMillis(tones);

        // Volume is applied as gain (dB) by the AudioPlayer: 100% = 0 dB.
        float gain = (float) (20.0 * Math.log10(
                Math.min(100, volume) / 100.0));

        try
        {
            executor.submit(() -> playSound(tones, gain));
        }
        catch (RuntimeException ex)
        {
            soundingUntilMillis = 0;
            log.debug("Could not schedule alert sound", ex);
        }
    }

    private void playSound(int[][] tones, float gain)
    {
        if (stopped)
        {
            return;
        }

        // Audio is optional; alerts still work without sound.
        try
        {
            audioPlayer.play(
                    new ByteArrayInputStream(toWav(render(tones))),
                    gain);
        }
        catch (Exception ex)
        {
            log.debug("Could not play alert sound", ex);
        }
    }

    private int getDurationMillis(int[][] tones)
    {
        int total = 0;

        for (int i = 0; i < tones.length; i++)
        {
            total += tones[i][1];

            if (i < tones.length - 1)
            {
                total += GAP_MS;
            }
        }

        return total;
    }

    /** Renders every tone, separated by short silences, as 16-bit PCM. */
    private byte[] render(int[][] tones)
    {
        int gapSamples = SAMPLE_RATE * GAP_MS / 1000;
        int totalSamples = 0;

        for (int i = 0; i < tones.length; i++)
        {
            totalSamples += SAMPLE_RATE * tones[i][1] / 1000;

            if (i < tones.length - 1)
            {
                totalSamples += gapSamples;
            }
        }

        byte[] buffer = new byte[totalSamples * 2];
        int offset = 0;

        for (int t = 0; t < tones.length; t++)
        {
            int frequency = tones[t][0];
            int samples = SAMPLE_RATE * tones[t][1] / 1000;

            for (int i = 0; i < samples; i++)
            {
                double angle = 2.0 * Math.PI * frequency * i / SAMPLE_RATE;

                double envelope = Math.min(
                        1.0,
                        Math.min(
                                i / (SAMPLE_RATE * 0.01),
                                (samples - i) / (SAMPLE_RATE * 0.02)
                        )
                );

                short value = (short) (
                        Math.sin(angle)
                                * Short.MAX_VALUE
                                * Math.max(0, envelope)
                );

                buffer[(offset + i) * 2] = (byte) (value & 0xff);
                buffer[(offset + i) * 2 + 1] = (byte) ((value >> 8) & 0xff);
            }

            // The gap after a tone is left as zeroes, i.e. silence.
            offset += samples + (t < tones.length - 1 ? gapSamples : 0);
        }

        return buffer;
    }

    /** Wraps raw 16-bit mono PCM in a standard 44-byte WAV header. */
    private byte[] toWav(byte[] pcm)
    {
        ByteBuffer wav = ByteBuffer
                .allocate(44 + pcm.length)
                .order(ByteOrder.LITTLE_ENDIAN);

        wav.put("RIFF".getBytes(StandardCharsets.US_ASCII));
        wav.putInt(36 + pcm.length);
        wav.put("WAVE".getBytes(StandardCharsets.US_ASCII));

        wav.put("fmt ".getBytes(StandardCharsets.US_ASCII));
        wav.putInt(16);                    // fmt chunk size
        wav.putShort((short) 1);           // PCM
        wav.putShort((short) 1);           // mono
        wav.putInt(SAMPLE_RATE);
        wav.putInt(SAMPLE_RATE * 2);       // byte rate
        wav.putShort((short) 2);           // block align
        wav.putShort((short) 16);          // bits per sample

        wav.put("data".getBytes(StandardCharsets.US_ASCII));
        wav.putInt(pcm.length);
        wav.put(pcm);

        return wav.array();
    }

    private int[][] getTones(AfkHelperConfig.AlertSound sound)
    {
        switch (sound)
        {
            case DOUBLE_BEEP:
                return new int[][] {
                        {880, 140},
                        {880, 140}
                };

            case BELL:
                return new int[][] {
                        {1046, 350}
                };

            case CHIME:
                return new int[][] {
                        {784, 160},
                        {988, 160},
                        {1175, 260}
                };

            case SIREN:
                return new int[][] {
                        {700, 180},
                        {1100, 180},
                        {700, 180},
                        {1100, 180}
                };

            case BEEP:
            default:
                return new int[][] {
                        {880, 180}
                };
        }
    }
}

package com.afkhelper;

import java.util.Map;

public class AfkHelperCombatCostSummary
{
    private final AfkHelperCombatCostTracker tracker;

    public AfkHelperCombatCostSummary(AfkHelperCombatCostTracker tracker)
    {
        this.tracker = tracker;
    }

    public long getTotalCost()
    {
        return tracker == null ? 0L : tracker.getTotalConsumedValue();
    }

    public double getCostPerHour()
    {
        return tracker == null ? 0.0 : tracker.getCostPerHour();
    }

    public String getTotalCostText()
    {
        return formatGp(getTotalCost());
    }

    public String getHourlyCostText()
    {
        return formatGp(Math.round(getCostPerHour())) + "/hr";
    }

    public String getSummary()
    {
        if (tracker == null)
        {
            return "Combat supplies: unavailable";
        }

        return "Combat supplies: " + getTotalCostText()
                + " (" + getHourlyCostText() + ")";
    }

    private String formatGp(long value)
    {
        if (value >= 1_000_000)
        {
            return String.format("%.2fm", value / 1_000_000.0);
        }

        if (value >= 1_000)
        {
            return String.format("%.1fk", value / 1_000.0);
        }

        return value + " gp";
    }
}

package com.afkhelper;

import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.game.ItemManager;

@Singleton
public class AfkHelperCombatCostTracker
{
    private final ItemManager itemManager;

    private final Map<Integer, Integer> previousItems = new HashMap<>();
    private final Map<Integer, Integer> consumedItems = new HashMap<>();
    private final Map<Integer, Long> itemPrices = new HashMap<>();

    private long totalConsumedValue;
    private long sessionStartTime;
    private boolean initialised;

    @Inject
    public AfkHelperCombatCostTracker(ItemManager itemManager)
    {
        this.itemManager = itemManager;
        reset();
    }

    public void updateInventory(int[] itemIds, int[] quantities)
    {
        updateCombined(itemIds, quantities, null, null, null, null);
    }

    public void updateEquipment(int[] itemIds, int[] quantities)
    {
        updateCombined(null, null, itemIds, quantities, null, null);
    }

    public void updateRunePouch(int[] runeIds, int[] runeAmounts)
    {
        updateCombined(null, null, null, null, runeIds, runeAmounts);
    }

    public void updateCombined(
            int[] inventoryIds,
            int[] inventoryQuantities,
            int[] equipmentIds,
            int[] equipmentQuantities,
            int[] runeIds,
            int[] runeAmounts)
    {
        Map<Integer, Integer> current = new HashMap<>();

        addItems(current, inventoryIds, inventoryQuantities);
        addItems(current, equipmentIds, equipmentQuantities);
        addItems(current, runeIds, runeAmounts);

        if (!initialised)
        {
            previousItems.putAll(current);
            initialised = true;
            return;
        }

        for (Map.Entry<Integer, Integer> entry : previousItems.entrySet())
        {
            int itemId = entry.getKey();
            int previousQuantity = entry.getValue();
            int currentQuantity = current.getOrDefault(itemId, 0);
            int difference = previousQuantity - currentQuantity;

            if (difference > 0 && isCombatSupply(itemId))
            {
                recordUsage(itemId, difference);
            }
        }

        previousItems.clear();
        previousItems.putAll(current);
    }

    private void addItems(
            Map<Integer, Integer> destination,
            int[] itemIds,
            int[] quantities)
    {
        if (itemIds == null || quantities == null)
        {
            return;
        }

        int length = Math.min(itemIds.length, quantities.length);

        for (int i = 0; i < length; i++)
        {
            int itemId = itemIds[i];
            int quantity = quantities[i];

            if (itemId > 0 && quantity > 0)
            {
                destination.merge(itemId, quantity, Integer::sum);
            }
        }
    }

    public void recordUsage(int itemId, int quantity)
    {
        if (itemId <= 0 || quantity <= 0 || !isCombatSupply(itemId))
        {
            return;
        }

        long price = itemPrices.computeIfAbsent(
                itemId,
                id -> itemManager.getItemPrice(id)
        );

        consumedItems.merge(itemId, quantity, Integer::sum);
        totalConsumedValue += price * quantity;
    }

    private boolean isCombatSupply(int itemId)
    {
        String name = itemManager.getItemComposition(itemId).getName();

        if (name == null)
        {
            return false;
        }

        String lower = name.toLowerCase();

        return lower.endsWith("arrow")
                || lower.endsWith("bolt")
                || lower.endsWith("dart")
                || lower.endsWith("javelin")
                || lower.endsWith("knife")
                || lower.endsWith("thrownaxe")
                || lower.endsWith("rune");
    }

    public long getTotalConsumedValue()
    {
        return totalConsumedValue;
    }

    public long getCostPerHour()
    {
        long elapsedSeconds = Math.max(
                1,
                (System.currentTimeMillis() - sessionStartTime) / 1000
        );

        return totalConsumedValue * 3600L / elapsedSeconds;
    }

    public Map<Integer, Integer> getItemsConsumed()
    {
        return new HashMap<>(consumedItems);
    }

    public int getConsumedQuantity(int itemId)
    {
        return consumedItems.getOrDefault(itemId, 0);
    }


    /**
     * Forget the previous inventory snapshot but keep the running totals,
     * so stats carry over to the next session without counting the
     * inventory loaded at login as items gained or used.
     */
    public void rebaseline()
    {
        previousItems.clear();
        initialised = false;
    }

    public void reset()
    {
        previousItems.clear();
        consumedItems.clear();
        itemPrices.clear();

        totalConsumedValue = 0;
        sessionStartTime = System.currentTimeMillis();
        initialised = false;
    }
}

package com.afkhelper;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Actor;
import net.runelite.api.NPC;

import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
public class AfkHelperCombatTracker
{
    private final AfkHelperSessionStats sessionStats;

    private final Map<Integer, Long> targetStartTimes = new HashMap<>();
    private final Map<Integer, Integer> targetDamage = new HashMap<>();
    private final Map<Integer, String> targetNames = new HashMap<>();

    @Inject
    public AfkHelperCombatTracker(AfkHelperSessionStats sessionStats)
    {
        this.sessionStats = sessionStats;
    }

    public void updateTarget(Actor actor)
    {
        if (!(actor instanceof NPC))
        {
            return;
        }

        NPC npc = (NPC) actor;
        int index = npc.getIndex();

        targetNames.put(index, npc.getName());

        targetStartTimes.putIfAbsent(index, System.currentTimeMillis());
    }

    public void recordDamage(Actor actor, int damage)
    {
        if (!(actor instanceof NPC) || damage <= 0)
        {
            return;
        }

        NPC npc = (NPC) actor;
        int index = npc.getIndex();

        updateTarget(npc);

        targetDamage.merge(index, damage, Integer::sum);
        sessionStats.recordDamage(npc.getName(), damage);
    }

    public void recordKill(Actor actor)
    {
        if (!(actor instanceof NPC))
        {
            return;
        }

        NPC npc = (NPC) actor;
        int index = npc.getIndex();

        Long startTime = targetStartTimes.remove(index);
        targetDamage.remove(index);
        targetNames.remove(index);

        if (startTime == null)
        {
            return;
        }

        long durationSeconds = Math.max(
                1,
                (System.currentTimeMillis() - startTime) / 1000
        );

        sessionStats.recordKillDuration(durationSeconds);
        sessionStats.recordMonsterKill(0);
    }

    public int getDamageForTarget(int npcIndex)
    {
        return targetDamage.getOrDefault(npcIndex, 0);
    }

    public String getTargetName(int npcIndex)
    {
        return targetNames.getOrDefault(npcIndex, "Unknown");
    }

    public int getTotalDamageForTarget(int npcIndex)
    {
        return getDamageForTarget(npcIndex);
    }

    public void reset()
    {
        targetStartTimes.clear();
        targetDamage.clear();
        targetNames.clear();
    }
}

