    private void addLevelUpSection()
    {
        JPanel details = createSection("Level-ups", false);

        addBooleanSetting(details, "Enable level-up notifications",
                config.levelUpNotifications(), "levelUpNotifications");
        addBooleanSetting(details, "Play level-up sound",
                config.levelUpSound(), "levelUpSound");
    }

    private void addAppearanceSection()
    {
        JPanel details = createSection("Appearance", false);

        addBooleanSetting(details, "Enable screen flash",
                config.screenFlash(), "screenFlash");
        addNumberSetting(details, "Flash opacity (%)",
                config.flashOpacity(), 1, 100, "flashOpacity");
        addNumberSetting(details, "Flash duration (milliseconds)",
                config.flashDuration(), 100, 5000, "flashDuration");
    }

    private void addAudioSection()
    {
        JPanel details = createSection("Audio", false);

        addBooleanSetting(details, "Enable audio alerts",
                config.audioEnabled(), "audioEnabled");

        details.add(createWrappedLabel("Default alert sound:"));

        JComboBox<AfkHelperConfig.AlertSound> soundSelector =
                new JComboBox<>(AfkHelperConfig.AlertSound.values());
        soundSelector.setSelectedItem(config.defaultSound());
        soundSelector.setMaximumSize(new Dimension(180, 28));
        soundSelector.setAlignmentX(LEFT_ALIGNMENT);

        soundSelector.addActionListener(e ->
                configManager.setConfiguration(
                        GROUP, "defaultSound", soundSelector.getSelectedItem()));

        details.add(soundSelector);
        details.add(Box.createVerticalStrut(8));

        addNumberSetting(details, "Audio volume (%)",
                config.audioVolume(), 0, 100, "audioVolume");
    }

    private void addActivityHighlightingSection()
    {
        JPanel details = createSection("Activity Highlighting", false);

        details.add(createWrappedLabel(
                "Highlight nearby activities you have the level to perform."));

        addBooleanSetting(details, "Enable eligible activity highlighting",
                config.eligibleActivityHighlightingEnabled(),
                "eligibleActivityHighlightingEnabled");
    }

    private JPanel createSection(String title, boolean expanded)
    {
        JPanel section = new JPanel();
        section.setLayout(new BoxLayout(section, BoxLayout.Y_AXIS));
        section.setAlignmentX(LEFT_ALIGNMENT);
        section.setBorder(BorderFactory.createEtchedBorder());
        section.setMaximumSize(
                new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

        JButton heading = new JButton(title);
        heading.setHorizontalAlignment(JButton.LEFT);
        heading.setAlignmentX(LEFT_ALIGNMENT);
        heading.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));

        JPanel details = new JPanel();
        details.setLayout(new BoxLayout(details, BoxLayout.Y_AXIS));
        details.setBorder(new EmptyBorder(6, 8, 8, 8));
        details.setAlignmentX(LEFT_ALIGNMENT);
        details.setMaximumSize(
                new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
        details.setVisible(expanded);

        heading.addActionListener(e ->
        {
            details.setVisible(!details.isVisible());
            section.revalidate();
            contentPanel.revalidate();
            contentPanel.repaint();
        });

        section.add(heading);
        section.add(details);

        contentPanel.add(section);
        contentPanel.add(Box.createVerticalStrut(6));

        return details;
    }

    private JCheckBox createWrappedCheckbox(
            String label,
            boolean selected)
    {
        JCheckBox checkbox = new JCheckBox();
        checkbox.putClientProperty("wrappedText", label);
        checkbox.setSelected(selected);
        checkbox.setAlignmentX(LEFT_ALIGNMENT);
        checkbox.setMaximumSize(
                new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

        checkbox.putClientProperty(
                "npcName",
                label.replaceFirst(" \\(\\d+ tiles\\)$", ""));

        wrappedCheckboxes.add(checkbox);
        updateCheckboxHtml(checkbox);

        return checkbox;
    }

    private void updateCheckboxHtml(JCheckBox checkbox)
    {
        Object value = checkbox.getClientProperty("wrappedText");

        if (value == null)
        {
            return;
        }

        checkbox.setText(
                "<html><body style='width:" + wrapWidth + "px'>"
                        + escapeHtml(value.toString())
                        + "</body></html>");
    }

    private void addBooleanSetting(
            JPanel panel,
            String label,
            boolean initialValue,
            String key)
    {
        JCheckBox checkbox = createWrappedCheckbox(label, initialValue);

        checkbox.addActionListener(e ->
                configManager.setConfiguration(
                        GROUP, key, checkbox.isSelected()));

        panel.add(checkbox);
    }

    private void addNumberSetting(
            JPanel panel,
            String label,
            int initialValue,
            int minimum,
            int maximum,
            String key)
    {
        panel.add(createWrappedLabel(label));

        JSpinner spinner = new JSpinner(
                new SpinnerNumberModel(initialValue, minimum, maximum, 1));
        spinner.setMaximumSize(new Dimension(120, 28));
        spinner.setAlignmentX(LEFT_ALIGNMENT);

        spinner.addChangeListener(e ->
                configManager.setConfiguration(
                        GROUP, key, spinner.getValue()));

        panel.add(spinner);
        panel.add(Box.createVerticalStrut(5));
    }

    private String htmlText(String text)
    {
        return "<html><body style='width:" + wrapWidth + "px'>"
                + escapeHtml(text)
                + "</body></html>";
    }
}

package com.afkhelper;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.function.Supplier;
import javax.inject.Inject;

import net.runelite.api.Client;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class AfkHelperSessionOverlay extends OverlayPanel
{
    private static final Color TITLE_COLOR = new Color(255, 190, 70);
    private static final Color SESSION_COLOR = new Color(100, 190, 255);
    private static final Color COMBAT_COLOR = new Color(255, 110, 100);
    private static final Color SUPPLY_COLOR = new Color(110, 220, 150);
    private static final Color VALUE_COLOR = new Color(245, 245, 245);

    private final AfkHelperSessionStats stats;
    private final AfkHelperInventoryTracker inventory;
    private final AfkHelperConfig config;

    private final Supplier<String> idleText;
    private final Supplier<String> combatText;
    private final Supplier<String> supplyText;
    private final Supplier<String> logoutText;

    @Inject
    public AfkHelperSessionOverlay(
            Client client,
            AfkHelperSessionStats stats,
            AfkHelperConfig config)
    {
        this(client, stats, null, config, null, null, null, null);
    }

    public AfkHelperSessionOverlay(
            Client client,
            AfkHelperSessionStats stats)
    {
        this(client, stats, null, null, null, null, null, null);
    }

    public AfkHelperSessionOverlay(
            Client client,
            AfkHelperSessionStats stats,
            AfkHelperInventoryTracker inventory)
    {
        this(client, stats, inventory, null, null, null, null, null);
    }

    public AfkHelperSessionOverlay(
            Client client,
            AfkHelperSessionStats stats,
            AfkHelperInventoryTracker inventory,
            Supplier<String> idleText,
            Supplier<String> combatText,
            Supplier<String> supplyText,
            Supplier<String> profitText)
    {
        this(
                client,
                stats,
                inventory,
                null,
                idleText,
                combatText,
                supplyText,
                profitText
        );
    }

    public AfkHelperSessionOverlay(
            Client client,
            AfkHelperSessionStats stats,
            AfkHelperInventoryTracker inventory,
            AfkHelperConfig config,
            Supplier<String> idleText,
            Supplier<String> combatText,
            Supplier<String> supplyText,
            Supplier<String> logoutText)
    {
        this.stats = stats;
        this.inventory = inventory;
        this.config = config;
        this.idleText = idleText;
        this.combatText = combatText;
        this.supplyText = supplyText;
        this.logoutText = logoutText;

        setPosition(OverlayPosition.TOP_LEFT);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        panelComponent.getChildren().clear();

        if (config != null && !config.sessionOverlayEnabled())
        {
            return null;
        }

        addTitle("AFK HELPER", TITLE_COLOR);

        addSection("SESSION", SESSION_COLOR);

        if (show("overlayShowDuration"))
        {
            addLine("Duration", stats.getSessionDurationText(), SESSION_COLOR);
        }

        if (show("overlayShowXpGained"))
        {
            addLine("XP gained", number(stats.getXpGained()), SESSION_COLOR);
        }

        if (show("overlayShowXpPerHour"))
        {
            addLine("XP / hour", number(stats.getXpPerHour()), SESSION_COLOR);
        }

        if (show("overlayShowActions"))
        {
            addLine("Actions", number(stats.getActions()), SESSION_COLOR);
        }

        if (show("overlayShowAfkStatus") && idleText != null)
        {
            addLine("AFK status", idleText.get(), SESSION_COLOR);
        }

        if (show("overlayShowLogoutCountdown") && logoutText != null)
        {
            addLine("Logout", logoutText.get(), SESSION_COLOR);
        }

        if (show("overlayShowCombatStatus") && combatText != null)
        {
            addLine("Combat status", combatText.get(), SESSION_COLOR);
        }

        addSection("COMBAT", COMBAT_COLOR);

        if (show("overlayShowKills"))
        {
            addLine("Kills", number(stats.getMonstersKilled()), COMBAT_COLOR);
        }

        if (show("overlayShowKillsPerHour"))
        {
            addLine("Kills / hour", number(stats.getKillsPerHour()), COMBAT_COLOR);
        }

        if (show("overlayShowDamage"))
        {
            addLine("Damage", number(stats.getTotalDamage()), COMBAT_COLOR);
        }

        if (show("overlayShowDamagePerHour"))
        {
            addLine("Damage / hour", number(stats.getDamagePerHour()), COMBAT_COLOR);
        }

        if (show("overlayShowAverageKillTime"))
        {
            addLine("Average kill", stats.getAverageKillTimeText(), COMBAT_COLOR);
        }

        if (inventory != null)
        {
            addSection("SUPPLIES & PROFIT", SUPPLY_COLOR);

            if (show("overlayShowSuppliesUsed"))
            {
                addLine("Supplies used", number(inventory.getSuppliesConsumed()), SUPPLY_COLOR);
            }

            if (show("overlayShowItemsGained"))
            {
                addLine("Items gained", number(inventory.getItemsGained()), SUPPLY_COLOR);
            }

            if (show("overlayShowEstimatedProfit"))
            {
                addLine("Estimated profit", gp(inventory.getEstimatedProfit()), SUPPLY_COLOR);
            }

            if (show("overlayShowSupplyCost"))
            {
                addLine("Supply cost", gp(inventory.getConsumableTotalCost()), SUPPLY_COLOR);
            }

            if (show("overlayShowSupplyCostPerHour"))
            {
                addLine("Supply cost / hour", gp(inventory.getConsumableCostPerHour()), SUPPLY_COLOR);
            }

            if (show("overlayShowCombatCost"))
            {
                addLine("Combat cost", gp(inventory.getCombatTotalCost()), SUPPLY_COLOR);
            }

            if (show("overlayShowCombatCostPerHour"))
            {
                addLine("Combat cost / hour", gp(inventory.getCombatCostPerHour()), SUPPLY_COLOR);
            }

            if (supplyText != null)
            {
                addLine("Supply summary", supplyText.get(), SUPPLY_COLOR);
            }
        }

        return super.render(graphics);
    }

    private boolean show(String key)
    {
        if (config == null)
        {
            return true;
        }

        switch (key)
        {
            case "overlayShowDuration":
                return config.overlayShowDuration();
            case "overlayShowXpGained":
                return config.overlayShowXpGained();
            case "overlayShowXpPerHour":
                return config.overlayShowXpPerHour();
            case "overlayShowActions":
                return config.overlayShowActions();
            case "overlayShowKills":
                return config.overlayShowKills();
            case "overlayShowKillsPerHour":
                return config.overlayShowKillsPerHour();
            case "overlayShowDamage":
                return config.overlayShowDamage();
            case "overlayShowDamagePerHour":
                return config.overlayShowDamagePerHour();
            case "overlayShowAverageKillTime":
                return config.overlayShowAverageKillTime();
            case "overlayShowAfkStatus":
                return config.overlayShowAfkStatus();
            case "overlayShowLogoutCountdown":
                return config.overlayShowLogoutCountdown();
            case "overlayShowCombatStatus":
                return config.overlayShowCombatStatus();
            case "overlayShowSuppliesUsed":
                return config.overlayShowSuppliesUsed();
            case "overlayShowItemsGained":
                return config.overlayShowItemsGained();
            case "overlayShowEstimatedProfit":
                return config.overlayShowEstimatedProfit();
            case "overlayShowSupplyCost":
                return config.overlayShowSupplyCost();
            case "overlayShowSupplyCostPerHour":
                return config.overlayShowSupplyCostPerHour();
            case "overlayShowCombatCost":
                return config.overlayShowCombatCost();
            case "overlayShowCombatCostPerHour":
                return config.overlayShowCombatCostPerHour();
            default:
                return true;
        }
    }

    private void addTitle(String text, Color color)
    {
        panelComponent.getChildren().add(
                TitleComponent.builder()
                        .text(text)
                        .color(color)
                        .build()
        );
    }

    private void addSection(String text, Color color)
    {
        panelComponent.getChildren().add(
                TitleComponent.builder()
                        .text(text)
                        .color(color)
                        .build()
        );
    }

    private void addLine(String label, String value, Color labelColor)
    {
        panelComponent.getChildren().add(
                LineComponent.builder()
                        .left(label)
                        .leftColor(labelColor)
                        .right(value == null ? "-" : value)
                        .rightColor(VALUE_COLOR)
                        .build()
        );
    }

    private String number(long value)
    {
        return String.format("%,d", value);
    }

    private String gp(long value)
    {
        return String.format("%,d gp", value);
    }
}

package com.afkhelper;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import net.runelite.api.Skill;

public class AfkHelperSessionStats
{
    private final Map<Skill, Integer> lastXp = new HashMap<>();
    private final Map<String, Integer> damageByMonster = new HashMap<>();

    private long sessionStartTime;
    private long currentKillStartTime;
    private long totalMonsterKillTimeSeconds;

    private int xpGained;
    private int actions;
    private int monstersKilled;
    private int combatXpGained;
    private int totalDamage;

    private final List<Long> completedKillTimes = new ArrayList<>();

    public void startSession(Map<Skill, Integer> currentXp, boolean reset)
    {
        if (reset)
        {
            reset();
        }

        lastXp.clear();

        if (currentXp != null)
        {
            lastXp.putAll(currentXp);
        }

        sessionStartTime = System.currentTimeMillis();
    }

    public void updateXp(Skill skill, int currentXp)
    {
        if (skill == null)
        {
            return;
        }

        Integer previousXp = lastXp.put(skill, currentXp);

        if (previousXp != null && currentXp > previousXp)
        {
            int gained = currentXp - previousXp;
            xpGained += gained;

            if (skill == Skill.ATTACK
                    || skill == Skill.STRENGTH
                    || skill == Skill.DEFENCE
                    || skill == Skill.HITPOINTS
                    || skill == Skill.RANGED
                    || skill == Skill.MAGIC
                    || skill == Skill.PRAYER)
            {
                combatXpGained += gained;
            }
        }
    }

    public void recordAction()
    {
        actions++;
    }

    public void recordMonsterKill(int xp)
    {
        monstersKilled++;
        combatXpGained += Math.max(0, xp);
    }

    public void startMonsterKill()
    {
        currentKillStartTime = System.currentTimeMillis();
    }

    public void recordDamage(String monsterName, int damage)
    {
        if (damage <= 0)
        {
            return;
        }

        totalDamage += damage;

        if (monsterName != null)
        {
            damageByMonster.merge(monsterName, damage, Integer::sum);
        }
    }

    public void recordKillDuration(long durationSeconds)
    {
        if (durationSeconds <= 0)
        {
            return;
        }

        completedKillTimes.add(durationSeconds);
        totalMonsterKillTimeSeconds += durationSeconds;
    }

    public int getXpGained()
    {
        return xpGained;
    }

    public long getXpPerHour()
    {
        long seconds = getSessionDurationSeconds();

        if (seconds <= 0)
        {
            return 0;
        }

        return xpGained * 3600L / seconds;
    }

    public int getActions()
    {
        return actions;
    }

    public int getMonstersKilled()
    {
        return monstersKilled;
    }

    public int getCombatXpGained()
    {
        return combatXpGained;
    }

    public int getTotalDamage()
    {
        return totalDamage;
    }

    public Map<String, Integer> getDamageByMonster()
    {
        return new HashMap<>(damageByMonster);
    }

    public long getSessionDurationSeconds()
    {
        if (sessionStartTime == 0)
        {
            return 0;
        }

        return Math.max(
                0,
                (System.currentTimeMillis() - sessionStartTime) / 1000
        );
    }

    public String getSessionDurationText()
    {
        return formatDuration(getSessionDurationSeconds());
    }

    public long getDamagePerHour()
    {
        long seconds = getSessionDurationSeconds();

        if (seconds <= 0)
        {
            return 0;
        }

        return totalDamage * 3600L / seconds;
    }

    public long getKillsPerHour()
    {
        long seconds = getSessionDurationSeconds();

        if (seconds <= 0)
        {
            return 0;
        }

        return monstersKilled * 3600L / seconds;
    }

    public long getAverageKillTimeSeconds()
    {
        if (completedKillTimes.isEmpty())
        {
            return 0;
        }

        return totalMonsterKillTimeSeconds / completedKillTimes.size();
    }

    public String getAverageKillTimeText()
    {
        if (completedKillTimes.isEmpty())
        {
            return "N/A";
        }

        return formatDuration(getAverageKillTimeSeconds());
    }

    public long getCurrentKillDurationSeconds()
    {
        if (currentKillStartTime == 0)
        {
            return 0;
        }

        return Math.max(
                0,
                (System.currentTimeMillis() - currentKillStartTime) / 1000
        );
    }

    public void reset()
    {
        lastXp.clear();
        damageByMonster.clear();
        completedKillTimes.clear();

        sessionStartTime = System.currentTimeMillis();
        currentKillStartTime = 0;
        totalMonsterKillTimeSeconds = 0;

        xpGained = 0;
        actions = 0;
        monstersKilled = 0;
        combatXpGained = 0;
        totalDamage = 0;
    }

    private String formatDuration(long totalSeconds)
    {
        long hours = totalSeconds / 3600;
        long minutes = (totalSeconds % 3600) / 60;
        long seconds = totalSeconds % 60;

        if (hours > 0)
        {
            return String.format("%d:%02d:%02d", hours, minutes, seconds);
        }

        return String.format("%02d:%02d", minutes, seconds);
    }
}

package com.afkhelper;

import java.util.HashMap;
import java.util.Map;

public class AfkHelperSupplyTracker
{
    private final Map<Integer, Integer> previousInventory = new HashMap<>();
    private final Map<Integer, Integer> suppliesConsumed = new HashMap<>();
    private final Map<Integer, Integer> itemsGained = new HashMap<>();

    private boolean initialised;

    public void updateInventory(int[] itemIds, int[] quantities)
    {
        if (itemIds == null || quantities == null
                || itemIds.length != quantities.length)
        {
            return;
        }

        Map<Integer, Integer> current = new HashMap<>();

        for (int i = 0; i < itemIds.length; i++)
        {
            if (itemIds[i] > 0 && quantities[i] > 0)
            {
                current.merge(itemIds[i], quantities[i], Integer::sum);
            }
        }

        if (!initialised)
        {
            previousInventory.putAll(current);
            initialised = true;
            return;
        }

        for (Map.Entry<Integer, Integer> entry : previousInventory.entrySet())
        {
            int id = entry.getKey();
            int difference = entry.getValue() - current.getOrDefault(id, 0);

            if (difference > 0)
            {
                suppliesConsumed.merge(id, difference, Integer::sum);
            }
        }

        for (Map.Entry<Integer, Integer> entry : current.entrySet())
        {
            int id = entry.getKey();
            int difference = entry.getValue() - previousInventory.getOrDefault(id, 0);

            if (difference > 0)
            {
                itemsGained.merge(id, difference, Integer::sum);
            }
        }

        previousInventory.clear();
        previousInventory.putAll(current);
    }

    public int getSuppliesConsumed(int itemId)
    {
        return suppliesConsumed.getOrDefault(itemId, 0);
    }

    public int getItemsGained(int itemId)
    {
        return itemsGained.getOrDefault(itemId, 0);
    }

    public int getTotalSuppliesConsumed()
    {
        return suppliesConsumed.values().stream()
                .mapToInt(Integer::intValue).sum();
    }

    public int getTotalItemsGained()
    {
        return itemsGained.values().stream()
                .mapToInt(Integer::intValue).sum();
    }

    public Map<Integer, Integer> getSuppliesConsumed()
    {
        return new HashMap<>(suppliesConsumed);
    }

    public Map<Integer, Integer> getItemsGained()
    {
        return new HashMap<>(itemsGained);
    }

    public String getSummary()
    {
        return "Consumed: " + getTotalSuppliesConsumed()
                + " | Gained: " + getTotalItemsGained();
    }


    /**
     * Forget the previous inventory snapshot but keep the running totals,
     * so stats carry over to the next session without counting the
     * inventory loaded at login as items gained or used.
     */
    public void rebaseline()
    {
        previousInventory.clear();
        initialised = false;
    }

    public void reset()
    {
        previousInventory.clear();
        suppliesConsumed.clear();
        itemsGained.clear();
        initialised = false;
    }
}

